import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.BFzNpupd.js";const g=JSON.parse('{"title":"🔄 Migration Guides","description":"","frontmatter":{},"headers":[],"relativePath":"guide/migration-guides.md","filePath":"guide/migration-guides.md"}'),n={name:"guide/migration-guides.md"};function o(r,e,l,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="🔄-migration-guides" tabindex="-1">🔄 Migration Guides <a class="header-anchor" href="#🔄-migration-guides" aria-label="Permalink to &quot;🔄 Migration Guides&quot;">​</a></h1><p>When upgrading between major or minor versions of the Veg Sahayyak SDK, you may encounter breaking changes or deprecated APIs. This guide provides step-by-step instructions to ensure a seamless transition for your integration.</p><h2 id="📌-sdk-deprecation-policy" tabindex="-1">📌 SDK Deprecation Policy <a class="header-anchor" href="#📌-sdk-deprecation-policy" aria-label="Permalink to &quot;📌 SDK Deprecation Policy&quot;">​</a></h2><p>To support our B2B and enterprise clients, we adhere to a strict deprecation lifecycle:</p><ol><li>APIs are <strong>never abruptly deleted</strong>.</li><li>Obsolete methods are marked with the <code>@Deprecated</code> annotation.</li><li>Deprecated methods are fully supported for exactly <strong>2 major versions</strong> before being removed.</li><li>Your IDE will automatically suggest the <code>ReplaceWith</code> equivalent code.</li></ol><hr><h2 id="migrating-from-v2-1-0-to-v2-2-0" tabindex="-1">Migrating from v2.1.0 to v2.2.0 <a class="header-anchor" href="#migrating-from-v2-1-0-to-v2-2-0" aria-label="Permalink to &quot;Migrating from v2.1.0 to v2.2.0&quot;">​</a></h2><p>Version 2.2.0 introduces the <strong>C++ Native Vault</strong> (<code>libveg_vault.so</code>) for offline cryptographic licensing.</p><h3 id="_1-telematicsengine-initialization-changed" tabindex="-1">1. <code>TelematicsEngine</code> Initialization Changed <a class="header-anchor" href="#_1-telematicsengine-initialization-changed" aria-label="Permalink to &quot;1. `TelematicsEngine` Initialization Changed&quot;">​</a></h3><p>Because the core math has been moved securely to C++, you can no longer instantiate <code>TelematicsEngine</code> directly without a license key.</p><p><strong>🔴 Old Code (v2.1.0):</strong></p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> engine </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TelematicsEngine</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p><strong>🟢 New Code (v2.2.0):</strong> You must now route all initialization through the <code>SpeedAssistant</code> builder and provide your JWT offline license key.</p><div class="language-kotlin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">kotlin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> speedAssistant </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SpeedAssistant.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(context, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_JWT_LICENSE_KEY_HERE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="_2-proguard-rules-update" tabindex="-1">2. ProGuard Rules Update <a class="header-anchor" href="#_2-proguard-rules-update" aria-label="Permalink to &quot;2. ProGuard Rules Update&quot;">​</a></h3><p>If you are using R8/ProGuard for minification, you must add the new Native JNI rules so the C++ bridge is not stripped during compilation.</p><p><strong>🟢 New Rule Required:</strong></p><div class="language-proguard vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">proguard</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Keep JNI bridge methods</span></span>\n<span class="line"><span>-keep class com.vegsahayyak.speedcore.math.SpatialResolver { *; }</span></span>\n<span class="line"><span>-keep class com.vegsahayyak.speedcore.math.LicenseManager { *; }</span></span></code></pre></div>',18)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
